/**
 * Stand-in for `schemastery`, which the Harness profile resolves at runtime.
 *
 * `lib/index.js` loads the real package lazily (a checkout without it still
 * activates with the row's config defaults), so this stub only has to exist
 * for the times the test runner asks for the name: nothing in the suite
 * exercises the schema itself.
 */

function noop() {
  return noop;
}

const Schema = new Proxy(noop, {
  get: () => noop,
  apply: () => noop,
});

export default Schema;
export { Schema };
export const z = Schema;
